use crate::flatten;
use crate::reader::{operand_boundary, validate_commas, Reader};
use crate::{failure, oom, Diagnostic, DiagnosticKind, ParseOptions, PathDocument, PathNumber, PathSegment, PathSubpath, MAX_PATH_COMMANDS, MAX_PATH_EDGES, MAX_PATH_NUMBERS};
use vexel_base::Span;
use vexel_geometry::{affine_valid, Affine, Point};

pub(crate) fn parse(source: &[u8], span: Span, transform: Affine, options: ParseOptions) -> Result<PathDocument, Diagnostic> {
    let bytes = span.slice(source).ok_or_else(|| failure(DiagnosticKind::InvalidSpan, span.start))?;
    if !affine_valid(transform) { return Err(failure(DiagnosticKind::InvalidTransform, span.start)); }
    validate_commas(bytes, span)?;
    Parser {
        reader: Reader { bytes, base: span.start, index: 0 },
        transform,
        flatness: flatten::tolerance(transform),
        max_commands: options.max_commands.min(MAX_PATH_COMMANDS),
        max_edges: options.max_edges.min(MAX_PATH_EDGES),
        max_numbers: options.max_numbers.min(MAX_PATH_NUMBERS),
        command_count: 0,
        document: PathDocument::new(),
    }.run()
}

struct Parser<'a> {
    reader: Reader<'a>,
    transform: Affine,
    flatness: f64,
    max_commands: usize,
    max_edges: usize,
    max_numbers: usize,
    command_count: usize,
    document: PathDocument,
}

impl Parser<'_> {
    fn run(mut self) -> Result<PathDocument, Diagnostic> {
        let (mut current, mut first, mut cubic_control, mut quad_control) = (Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 }, Point { x: 0.0, y: 0.0 });
        let (mut command, mut open, mut path_first) = (0u8, false, true);
        let (mut cubic_reflect, mut quad_reflect) = (false, false);
        let (mut previous_number, mut previous_arc_flag) = (false, false);
        let mut current_subpath_edge = 0;
        let mut last_group_offset = self.reader.base;

        while self.reader.index < self.reader.bytes.len() {
            let gap_start = self.reader.index;
            self.reader.skip_separators();
            let had_separator = self.reader.index != gap_start;
            if self.reader.index >= self.reader.bytes.len() { break; }
            let segment_start = self.reader.index;
            let mut command_offset = None;
            if self.reader.bytes[self.reader.index].is_ascii_alphabetic() {
                command_offset = Some(self.reader.absolute());
                command = self.reader.bytes[self.reader.index];
                self.reader.index += 1;
                previous_number = false;
            } else if command == 0 || command == b'Z' || command == b'z' {
                return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
            } else {
                if previous_number && !had_separator && !matches!(self.reader.bytes[self.reader.index], b'+' | b'-') {
                    return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
                }
                previous_number = false;
            }
            self.command_count = self.command_count.checked_add(1).ok_or_else(|| failure(DiagnosticKind::Limit, self.reader.absolute()))?;
            if self.command_count > self.max_commands { return Err(failure(DiagnosticKind::Limit, self.reader.absolute())); }
            let segment_command = command;
            let relative = command.is_ascii_lowercase();
            let upper = command.to_ascii_uppercase();
            if path_first && upper != b'M' { return Err(failure(DiagnosticKind::Path, self.reader.absolute().saturating_sub(1))); }
            path_first = false;

            if upper == b'Z' {
                let first_edge = self.document.edges.len();
                if open {
                    self.add_edge(current, first, last_group_offset)?;
                    self.record_subpath(current_subpath_edge, true, last_group_offset)?;
                }
                let segment_index = self.record_segment(segment_command, segment_start, self.reader.index, command_offset, &[], first_edge)?;
                self.document.segments[segment_index].edge_count = self.document.edges.len() - first_edge;
                current = first;
                open = false;
                command = 0;
                cubic_reflect = false;
                quad_reflect = false;
                continue;
            }
            if !matches!(upper, b'M' | b'L' | b'H' | b'V' | b'C' | b'S' | b'Q' | b'T' | b'A') {
                return Err(failure(DiagnosticKind::Unsupported, self.reader.absolute().saturating_sub(1)));
            }
            let count = match upper { b'H' | b'V' => 1, b'C' => 6, b'S' | b'Q' => 4, b'T' => 2, b'A' => 7, _ => 2 };
            let group_start = self.reader.index;
            last_group_offset = self.reader.base + group_start;
            let mut values = [0.0; 7];
            let mut source_numbers = [PathNumber { source: Span { start: 0, end: 0 }, value: 0.0 }; 7];
            for index in 0..count {
                if !operand_boundary(&mut self.reader, previous_number, previous_arc_flag, upper, index) {
                    return Err(failure(DiagnosticKind::Path, self.reader.absolute()));
                }
                let parsed = if upper == b'A' && (index == 3 || index == 4) { self.reader.arc_flag() } else { self.reader.number() };
                let (value, source_span) = parsed.map_err(|_| failure(DiagnosticKind::Path, self.reader.base + group_start))?;
                values[index] = value;
                source_numbers[index] = PathNumber { source: source_span, value };
                previous_number = true;
                previous_arc_flag = upper == b'A' && (index == 3 || index == 4);
            }
            let first_edge = self.document.edges.len();
            let segment_index = self.record_segment(segment_command, segment_start, self.reader.index, command_offset, &source_numbers[..count], first_edge)?;
            let mut point = current;
            let mut drawn = false;
            match upper {
                b'H' => point.x = if relative { current.x + values[0] } else { values[0] },
                b'V' => point.y = if relative { current.y + values[0] } else { values[0] },
                b'C' => {
                    let mut c1 = Point { x: values[0], y: values[1] };
                    let mut c2 = Point { x: values[2], y: values[3] };
                    point = Point { x: values[4], y: values[5] };
                    if relative { c1 = add(c1, current); c2 = add(c2, current); point = add(point, current); }
                    self.check_points(&[c1, c2, point], group_start)?;
                    self.add_curve([current, c1, c2, point], self.reader.base + group_start)?;
                    cubic_control = c2;
                    cubic_reflect = true;
                    quad_reflect = false;
                    drawn = true;
                }
                b'S' => {
                    let c1 = if cubic_reflect { reflect(current, cubic_control) } else { current };
                    let mut c2 = Point { x: values[0], y: values[1] };
                    point = Point { x: values[2], y: values[3] };
                    if relative { c2 = add(c2, current); point = add(point, current); }
                    self.check_points(&[c1, c2, point], group_start)?;
                    self.add_curve([current, c1, c2, point], self.reader.base + group_start)?;
                    cubic_control = c2;
                    cubic_reflect = true;
                    quad_reflect = false;
                    drawn = true;
                }
                b'Q' => {
                    let mut control = Point { x: values[0], y: values[1] };
                    point = Point { x: values[2], y: values[3] };
                    if relative { control = add(control, current); point = add(point, current); }
                    self.check_points(&[control, point], group_start)?;
                    self.add_quad(current, control, point, self.reader.base + group_start)?;
                    quad_control = control;
                    quad_reflect = true;
                    cubic_reflect = false;
                    drawn = true;
                }
                b'T' => {
                    let control = if quad_reflect { reflect(current, quad_control) } else { current };
                    point = Point { x: values[0], y: values[1] };
                    if relative { point = add(point, current); }
                    self.check_points(&[control, point], group_start)?;
                    self.add_quad(current, control, point, self.reader.base + group_start)?;
                    quad_control = control;
                    quad_reflect = true;
                    cubic_reflect = false;
                    drawn = true;
                }
                b'A' => {
                    if (values[3] != 0.0 && values[3] != 1.0) || (values[4] != 0.0 && values[4] != 1.0) || values[0] < 0.0 || values[1] < 0.0 {
                        return Err(failure(DiagnosticKind::Path, self.reader.base + group_start));
                    }
                    point = Point { x: values[5], y: values[6] };
                    if relative { point = add(point, current); }
                    self.check_points(&[point], group_start)?;
                    flatten::arc(&mut self.document.edges, self.transform, current, values[0], values[1], values[2], values[3] == 1.0, values[4] == 1.0, point, self.flatness, self.max_edges, self.reader.base + group_start)?;
                    cubic_reflect = false;
                    quad_reflect = false;
                    drawn = true;
                }
                _ => {
                    point = Point { x: values[0], y: values[1] };
                    if relative { point = add(point, current); }
                    if upper == b'M' {
                        self.check_points(&[point], group_start)?;
                        if open {
                            self.add_edge(current, first, self.reader.base + group_start)?;
                            self.record_subpath(current_subpath_edge, false, self.reader.base + group_start)?;
                        }
                        current = point;
                        first = point;
                        current_subpath_edge = self.document.edges.len();
                        open = true;
                        command = if relative { b'l' } else { b'L' };
                        cubic_reflect = false;
                        quad_reflect = false;
                        continue;
                    }
                }
            }
            if matches!(upper, b'M' | b'L' | b'H' | b'V') { cubic_reflect = false; quad_reflect = false; }
            self.check_points(&[point], group_start)?;
            if !drawn { self.add_edge(current, point, self.reader.base + group_start)?; }
            self.document.segments[segment_index].edge_count = self.document.edges.len() - first_edge;
            current = point;
            open = true;
        }
        if open {
            self.add_edge(current, first, last_group_offset)?;
            self.record_subpath(current_subpath_edge, false, last_group_offset)?;
        }
        Ok(self.document)
    }

    fn check_points(&self, points: &[Point], group_start: usize) -> Result<(), Diagnostic> {
        if points.iter().all(|point| flatten::bounded(*point)) { Ok(()) } else { Err(failure(DiagnosticKind::Number, self.reader.base + group_start)) }
    }
    fn add_edge(&mut self, from: Point, to: Point, offset: usize) -> Result<(), Diagnostic> {
        flatten::edge(&mut self.document.edges, self.transform, from, to, self.max_edges, offset)
    }
    fn add_curve(&mut self, points: [Point; 4], offset: usize) -> Result<(), Diagnostic> {
        flatten::curve(&mut self.document.edges, self.transform, points, self.flatness, self.max_edges, offset)
    }
    fn add_quad(&mut self, from: Point, control: Point, to: Point, offset: usize) -> Result<(), Diagnostic> {
        let c1 = Point { x: from.x + (control.x - from.x) * (2.0 / 3.0), y: from.y + (control.y - from.y) * (2.0 / 3.0) };
        let c2 = Point { x: to.x + (control.x - to.x) * (2.0 / 3.0), y: to.y + (control.y - to.y) * (2.0 / 3.0) };
        self.add_curve([from, c1, c2, to], offset)
    }
    fn record_subpath(&mut self, first_edge: usize, closed: bool, offset: usize) -> Result<(), Diagnostic> {
        let edge_count = self.document.edges.len() - first_edge;
        if edge_count == 0 { return Ok(()); }
        if self.document.subpaths.len() >= MAX_PATH_EDGES { return Err(failure(DiagnosticKind::Limit, offset)); }
        self.document.subpaths.try_reserve(1).map_err(|_| oom(offset))?;
        self.document.subpaths.push(PathSubpath { first_edge, edge_count, closed });
        Ok(())
    }
    fn record_segment(&mut self, command: u8, start: usize, end: usize, command_offset: Option<usize>, numbers: &[PathNumber], first_edge: usize) -> Result<usize, Diagnostic> {
        let offset = self.reader.base + start;
        if self.document.segments.len() >= self.max_commands || numbers.len() > self.max_numbers.saturating_sub(self.document.numbers.len()) {
            return Err(failure(DiagnosticKind::Limit, offset));
        }
        self.document.segments.try_reserve(1).map_err(|_| oom(offset))?;
        self.document.numbers.try_reserve(numbers.len()).map_err(|_| oom(offset))?;
        let first_number = self.document.numbers.len();
        self.document.numbers.extend_from_slice(numbers);
        let index = self.document.segments.len();
        self.document.segments.push(PathSegment {
            command,
            source: Span { start: offset, end: self.reader.base + end },
            command_offset,
            first_number,
            number_count: numbers.len(),
            first_edge,
            edge_count: 0,
        });
        Ok(index)
    }
}

fn add(a: Point, b: Point) -> Point { Point { x: a.x + b.x, y: a.y + b.y } }
fn reflect(origin: Point, control: Point) -> Point { Point { x: 2.0 * origin.x - control.x, y: 2.0 * origin.y - control.y } }
use crate::{Diagnostic, DiagnosticKind};
use vexel_base::Span;

pub(crate) struct Reader<'a> { pub bytes: &'a [u8], pub base: usize, pub index: usize }

impl<'a> Reader<'a> {
    pub(crate) fn absolute(&self) -> usize { self.base + self.index }
    pub(crate) fn skip_space(&mut self) {
        while matches!(self.bytes.get(self.index), Some(b' ' | b'\t' | b'\r' | b'\n')) { self.index += 1; }
    }
    pub(crate) fn skip_separators(&mut self) {
        while matches!(self.bytes.get(self.index), Some(b' ' | b'\t' | b'\r' | b'\n' | b',')) { self.index += 1; }
    }
    pub(crate) fn number(&mut self) -> Result<(f64, Span), Diagnostic> {
        self.skip_space();
        let start = self.index;
        let negative = match self.bytes.get(self.index) {
            Some(b'-') => { self.index += 1; true },
            Some(b'+') => { self.index += 1; false },
            _ => false,
        };
        let mut value = 0.0;
        let mut digits = 0usize;
        while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
            value = value * 10.0 + f64::from(byte - b'0');
            self.index += 1;
            digits += 1;
            if !value.is_finite() || value > 1.0e300 { return Err(self.number_error()); }
        }
        if self.bytes.get(self.index) == Some(&b'.') {
            self.index += 1;
            let mut scale = 0.1;
            while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
                value += f64::from(byte - b'0') * scale;
                scale *= 0.1;
                self.index += 1;
                digits += 1;
            }
        }
        if digits == 0 { self.index = start; return Err(self.number_error()); }
        if matches!(self.bytes.get(self.index), Some(b'e' | b'E')) {
            let mut lookahead = self.index + 1;
            if matches!(self.bytes.get(lookahead), Some(b'+' | b'-')) { lookahead += 1; }
            if matches!(self.bytes.get(lookahead), Some(b'0'..=b'9')) {
                self.index += 1;
                let exponent_negative = match self.bytes.get(self.index) {
                    Some(b'-') => { self.index += 1; true },
                    Some(b'+') => { self.index += 1; false },
                    _ => false,
                };
                let mut exponent = 0i32;
                while let Some(byte @ b'0'..=b'9') = self.bytes.get(self.index).copied() {
                    if exponent < 10_000 { exponent = exponent.saturating_mul(10).saturating_add(i32::from(byte - b'0')); }
                    self.index += 1;
                }
                if exponent_negative { exponent = -exponent; }
                value *= 10.0_f64.powi(exponent);
            }
        }
        if negative { value = -value; }
        if !value.is_finite() || value.abs() > 1.0e6 { return Err(self.number_error()); }
        Ok((value, Span { start: self.base + start, end: self.absolute() }))
    }
    pub(crate) fn arc_flag(&mut self) -> Result<(f64, Span), Diagnostic> {
        self.skip_space();
        let start = self.index;
        match self.bytes.get(self.index) {
            Some(b'0' | b'1') => {
                let value = f64::from(self.bytes[self.index] - b'0');
                self.index += 1;
                Ok((value, Span { start: self.base + start, end: self.absolute() }))
            }
            _ => Err(self.number_error()),
        }
    }
    fn number_error(&self) -> Diagnostic { Diagnostic { kind: DiagnosticKind::Path, offset: self.absolute() } }
}

pub(crate) fn operand_boundary(reader: &mut Reader<'_>, previous_number: bool, previous_arc_flag: bool, command: u8, argument: usize) -> bool {
    let before = reader.index;
    reader.skip_separators();
    if !previous_number || reader.index != before { return true; }
    if matches!(reader.bytes.get(reader.index), Some(b'+' | b'-' | b'.')) { return true; }
    command == b'A' && (argument == 4 || (argument == 5 && previous_arc_flag))
}

pub(crate) fn validate_commas(bytes: &[u8], span: Span) -> Result<(), Diagnostic> {
    for (index, byte) in bytes.iter().enumerate() {
        if *byte != b',' { continue; }
        let mut left = index;
        let mut right = index + 1;
        while left > 0 && is_space(bytes[left - 1]) { left -= 1; }
        while right < bytes.len() && is_space(bytes[right]) { right += 1; }
        let left_ok = left > 0 && (bytes[left - 1].is_ascii_digit() || bytes[left - 1] == b'.');
        let right_ok = right < bytes.len() && (bytes[right].is_ascii_digit() || matches!(bytes[right], b'.' | b'+' | b'-'));
        if !left_ok || !right_ok || bytes.get(left.wrapping_sub(1)) == Some(&b',') || bytes.get(right) == Some(&b',') {
            return Err(Diagnostic { kind: DiagnosticKind::Path, offset: span.start + index });
        }
    }
    Ok(())
}

fn is_space(byte: u8) -> bool { matches!(byte, b' ' | b'\t' | b'\r' | b'\n') }

use vexel_base::Span;
use vexel_geometry::{affine_identity, Affine, Edge, Point};
use vexel_svg_path::{append_edge, flatten_cubic, parse_path, transformed_tolerance, Diagnostic, DiagnosticKind, ParseOptions, MAX_COORDINATE, MAX_PATH_COMMANDS, MAX_PATH_EDGES, MAX_PATH_NUMBERS};
use vexel_base::{BudgetControl, ControlledError};
use std::sync::atomic::AtomicBool;

fn parse(data: &[u8]) -> vexel_svg_path::PathDocument {
    parse_path(data, Span { start: 0, end: data.len() }, affine_identity(), ParseOptions::default()).unwrap()
}

fn close(actual: f64, expected: f64) { assert!((actual - expected).abs() <= 1e-10, "{actual} != {expected}"); }

#[test]
fn supports_every_command_relative_forms_and_authored_command_provenance() {
    let path = parse(b"M1 2 L3 4 h2 v-1 C6 5 7 6 8 7 s2 2 3 3 Q12 12 14 10 t2 0 A2 3 0 0 1 19 12 z");
    assert_eq!(path.segments.iter().map(|segment| segment.command).collect::<Vec<_>>(), b"MLhvCsQtAz");
    assert_eq!(path.subpaths.len(), 1);
    assert!(path.subpaths[0].closed);
    assert_eq!(path.subpaths[0].first_edge, 0);
    assert!(path.subpaths[0].edge_count > 8);
    for segment in &path.segments {
        assert!(segment.source.start < segment.source.end);
        assert_eq!(segment.number_count, if segment.command.to_ascii_uppercase() == b'Z' { 0 } else { path.numbers[segment.first_number..segment.first_number + segment.number_count].len() });
    }
    assert_eq!(path.numbers.len(), 29);
}

#[test]
fn implicit_repeats_move_to_lines_and_subpath_closure_match_reference() {
    let path = parse(b"M1 1 4 1 4 4 M8 8 l2 0 z");
    assert_eq!(path.segments.iter().map(|segment| segment.command).collect::<Vec<_>>(), b"MLLMlz");
    assert_eq!(path.segments[0].command_offset, Some(0));
    assert_eq!(path.segments[1].command_offset, None);
    assert_eq!(path.subpaths.len(), 2);
    assert!(!path.subpaths[0].closed);
    assert!(path.subpaths[1].closed);
    assert_eq!(path.subpaths[0].edge_count, 3);
    assert_eq!(path.subpaths[1].edge_count, 2);
    assert_eq!(path.edges[2].a, Point { x: 4.0, y: 4.0 });
    assert_eq!(path.edges[2].b, Point { x: 1.0, y: 1.0 });
}

#[test]
fn smooth_reflection_and_reset_rules_have_exact_control_geometry() {
    let cubic = parse(b"M0 0 C1 0 2 0 3 0 S5 1 6 0 L7 0 S8 1 9 0");
    let first_cubic = cubic.edges.iter().position(|edge| edge.a == Point { x: 3.0, y: 0.0 }).unwrap();
    assert_eq!(cubic.edges[first_cubic].b, Point { x: 4.5, y: 0.375 });
    let reset_start = cubic.edges.iter().position(|edge| edge.a == Point { x: 7.0, y: 0.0 }).unwrap();
    assert_eq!(cubic.edges[reset_start].b, Point { x: 7.625, y: 0.375 });

    let quad = parse(b"M0 0 Q2 2 4 0 T8 0 L9 0 T11 0");
    let reflected_start = quad.edges.iter().position(|edge| edge.a == Point { x: 4.0, y: 0.0 }).unwrap();
    assert!(quad.edges[reflected_start].b.y < 0.0);
    let reflected_segment = &quad.segments[2];
    let reflected_end = reflected_segment.first_edge + reflected_segment.edge_count - 1;
    assert_eq!(quad.edges[reflected_end].b, Point { x: 8.0, y: 0.0 });
    let reset_start = quad.edges.iter().position(|edge| edge.a == Point { x: 9.0, y: 0.0 }).unwrap();
    assert_eq!(quad.edges[reset_start].a, Point { x: 9.0, y: 0.0 });
}

#[test]
fn compact_numbers_and_arc_flags_keep_exact_source_ranges() {
    let source = b"prefix M-.4.6A2 3 0 011.2.4 suffix";
    let start = 7;
    let end = source.len() - 7;
    let path = parse_path(source, Span { start, end }, affine_identity(), ParseOptions::default()).unwrap();
    assert_eq!(path.numbers.len(), 9);
    let literals: [&[u8]; 9] = [b"-.4", b".6", b"2", b"3", b"0", b"0", b"1", b"1.2", b".4"];
    let mut search = start + 1;
    for (number, literal) in path.numbers.iter().zip(literals) {
        let relative = source[search..end].windows(literal.len()).position(|window| window == literal).unwrap();
        let expected_offset = search + relative;
        assert_eq!(number.source.start, expected_offset);
        assert_eq!(&source[number.source.start..number.source.end], literal);
        search = number.source.end;
    }
    close(path.numbers[0].value, -0.4);
    close(path.numbers[1].value, 0.6);
    assert_eq!(path.segments[0].source, Span { start, end: start + 6 });
    assert_eq!(path.segments[1].command_offset, Some(start + 6));
}

#[test]
fn arcs_cover_degenerate_same_end_corrected_and_flag_validation_cases() {
    let zero_radius = parse(b"M0 0 A0 3 0 0 1 4 5");
    assert_eq!(zero_radius.edges.len(), 2);
    assert_eq!(zero_radius.edges[0].b, Point { x: 4.0, y: 5.0 });
    let same_point = parse(b"M2 2 A3 4 45 1 1 2 2");
    assert_eq!(same_point.edges.len(), 1);
    let corrected = parse(b"M0 0 A1 1 0 0 1 10 0");
    assert!(corrected.edges.len() >= 2);
    assert_eq!(corrected.edges[corrected.edges.len() - 2].b, Point { x: 10.0, y: 0.0 });
    assert_eq!(corrected.edges.last().unwrap().b, Point { x: 0.0, y: 0.0 });
    for data in [b"M0 0 A1 1 0 2 0 4 4".as_slice(), b"M0 0 A-1 1 0 0 0 4 4", b"M0 0 A1 1 0 0.0 0 4 4"] {
        let error = parse_path(data, Span { start: 0, end: data.len() }, affine_identity(), ParseOptions::default()).unwrap_err();
        assert_eq!(error.kind, DiagnosticKind::Path);
        assert_eq!(error.offset, 6);
    }
}

#[test]
fn transform_changes_edge_coordinates_and_flatness() {
    let data = b"M0 0 C0 10 10 10 10 0";
    let identity = parse(data);
    let scale = Affine { a: 4.0, d: 4.0, ..affine_identity() };
    let scaled = parse_path(data, Span { start: 0, end: data.len() }, scale, ParseOptions::default()).unwrap();
    assert!(scaled.edges.len() > identity.edges.len());
    assert_eq!(scaled.edges.first().unwrap().a, Point { x: 0.0, y: 0.0 });
    assert_eq!(scaled.edges[scaled.edges.len() - 2].b, Point { x: 40.0, y: 0.0 });
    let translated = Affine { e: 12.0, f: -5.0, ..affine_identity() };
    let line = parse_path(b"M1 2L3 4", Span { start: 0, end: 8 }, translated, ParseOptions::default()).unwrap();
    assert_eq!(line.edges[0].a, Point { x: 13.0, y: -3.0 });
    assert_eq!(line.edges[0].b, Point { x: 15.0, y: -1.0 });
}

