    let options = ParseOptions { max_commands: 1, ..ParseOptions::default() };
    let error = parse_path(b"M0 0L1 1", Span { start: 0, end: 8 }, affine_identity(), options).unwrap_err();
    assert_eq!(error.kind, DiagnosticKind::Limit);
    assert_eq!(error.offset, 5);
    let options = ParseOptions { max_edges: 1, ..ParseOptions::default() };
    let error = parse_path(b"M0 0L1 1", Span { start: 0, end: 8 }, affine_identity(), options).unwrap_err();
    assert_eq!(error.kind, DiagnosticKind::Limit);
    assert_eq!(error.offset, 5);
    let options = ParseOptions { max_numbers: 1, ..ParseOptions::default() };
    let error = parse_path(b"M0 0", Span { start: 0, end: 4 }, affine_identity(), options).unwrap_err();
    assert_eq!(error.kind, DiagnosticKind::Limit);
    assert_eq!(error.offset, 0);
    for (data, offset, kind) in [(b"L0 0".as_slice(), 0, DiagnosticKind::Path), (b"M0 0X".as_slice(), 4, DiagnosticKind::Unsupported)] {
        let error = parse_path(data, Span { start: 0, end: data.len() }, affine_identity(), ParseOptions::default()).unwrap_err();
        assert_eq!(error.offset, offset);
        assert_eq!(error.kind, kind);
    }
    assert_eq!(ParseOptions::default().max_commands, MAX_PATH_COMMANDS);
    assert_eq!(ParseOptions::default().max_edges, MAX_PATH_EDGES);
    assert_eq!(ParseOptions::default().max_numbers, MAX_PATH_NUMBERS);
}

