                    Some(byte @ (b'0' | b'1')) => {
                        self.reader.take()?;
                        self.operand(PathNumber { source: Span { start, end: self.reader.absolute() }, value: f64::from(byte - b'0') })?;
                    }
                    _ => return Err(ControlledError::Original(failure(DiagnosticKind::Path, self.group_offset()))),
                }
            }
            Phase::RecordReserve => self.reserve_segment()?,
            Phase::RecordNumber => {
                self.document.numbers.push(self.group.numbers[self.group.metadata_index]);
                self.group.metadata_index = self.group.metadata_index.checked_add(1).ok_or(ControlledError::Overflow)?;
                if self.group.metadata_index == self.group.count { self.phase = Phase::RecordSegment; }
            }
            Phase::RecordSegment => {
                let offset = self.reader.base + self.group.start;
                self.group.segment_index = self.document.segments.len();
                self.document.segments.push(PathSegment { command: self.group.command,
                    source: Span { start: offset, end: self.reader.base + self.group.end }, command_offset: self.group.command_offset,
                    first_number: self.group.first_number, number_count: self.group.count, first_edge: self.group.first_edge, edge_count: 0 });
                self.phase = if self.group.upper == b'Z' { Phase::FinishClose } else { Phase::Apply };
            }
            Phase::Apply => self.apply_group()?,
            Phase::Geometry => {
                let cursor = self.geometry.as_mut().ok_or(ControlledError::Overflow)?;
                if cursor.advance(&mut self.document.edges, self.transform, self.flatness, self.max_edges, self.geometry_offset)? {
                    self.geometry = None;
                    self.phase = match self.after_geometry {
                        AfterGeometry::Group => Phase::CompleteGroup, AfterGeometry::Move => Phase::MoveSubpath,
                        AfterGeometry::Close => Phase::CloseSubpath, AfterGeometry::Final => Phase::FinalSubpath,
                    };
                }
            }
            Phase::MoveSubpath => { self.record_subpath(false, self.group_offset())?; self.phase = Phase::FinishMove; }
            Phase::FinishMove => {
                self.current = self.group.point; self.first = self.group.point;
                self.current_subpath_edge = self.document.edges.len(); self.open = true;
                self.command = if self.group.relative { b'l' } else { b'L' };
                self.cubic_reflect = false; self.quad_reflect = false;
                self.next_gap();
            }
            Phase::CloseSubpath => { self.record_subpath(true, self.last_group_offset)?; self.phase = Phase::RecordReserve; }
            Phase::FinishClose => {
                self.complete_segment()?;
                self.current = self.first; self.open = false; self.command = 0;
                self.cubic_reflect = false; self.quad_reflect = false;
                self.next_gap();
            }
            Phase::CompleteGroup => {
                self.check_points(&[self.group.point])?;
                self.complete_segment()?;
                self.current = self.group.point; self.open = true;
                self.next_gap();
            }
            Phase::FinalSubpath => { self.record_subpath(false, self.last_group_offset)?; self.phase = Phase::Done; }
            Phase::Done | Phase::Failed => (),
        }
        Ok(())
    }
    fn begin_group(&mut self) -> Result<(), ControlledError<Diagnostic>> {
        self.group = Group::new();
        self.group.start = self.reader.index;
        self.group.first_edge = self.document.edges.len();
        let byte = self.reader.peek().ok_or(ControlledError::Overflow)?;
        if byte.is_ascii_alphabetic() {
            self.group.command_offset = Some(self.reader.absolute());
            self.command = byte; self.reader.take()?; self.previous_number = false;
        } else if self.command == 0 || matches"'!(self.command, b'"'Z' | b'z') {
            return Err(ControlledError::Original(failure(DiagnosticKind::Path, self.reader.absolute())));
        } else {
            if self.previous_number && "'!self.had_separator && !matches!(byte, b'"'+' | b'-') {
                return Err(ControlledError::Original(failure(DiagnosticKind::Path, self.reader.absolute())));
            }
            self.previous_number = false;
        }
        self.command_count = self.command_count.checked_add(1).ok_or(ControlledError::Overflow)?;
        if self.command_count > self.max_commands { return Err(ControlledError::Original(failure(DiagnosticKind::Limit, self.reader.absolute()))); }
        self.group.command = self.command;
        self.group.relative = self.command.is_ascii_lowercase();
        self.group.upper = self.command.to_ascii_uppercase();
        if self.path_first && self.group.upper "'!= b'"'M' {
            return Err(ControlledError::Original(failure(DiagnosticKind::Path, self.reader.absolute().saturating_sub(1))));
        }
        self.path_first = false;
        if self.group.upper == b'Z' {
            if self.open { self.start_geometry(GeometryCursor::Line(self.current, self.first), self.last_group_offset, AfterGeometry::Close); }
            else { self.phase = Phase::RecordReserve; }
            return Ok(());
        }
        self.group.count = match self.group.upper {
            b'H' | b'V' => 1, b'C' => 6, b'S' | b'Q' => 4, b'T' | b'M' | b'L' => 2, b'A' => 7,
            _ => return Err(ControlledError::Original(failure(DiagnosticKind::Unsupported, self.reader.absolute().saturating_sub(1)))),
        };
        self.group.group_start = self.reader.index;
        self.last_group_offset = self.group_offset();
        self.had_separator = false;
        self.phase = Phase::OperandGap;
        Ok(())
    }
    fn operand(&mut self, number: PathNumber) -> Result<(), ControlledError<Diagnostic>> {
        self.group.numbers[self.group.operand] = number;
        self.previous_number = true;
        self.previous_arc_flag = self.group.upper == b'A' && matches"'!(self.group.operand, 3 | 4);
        self.group.operand = self.group.operand.checked_add(1).ok_or(ControlledError::Overflow)?;
        self.had_separator = false;
        self.phase = if self.group.operand == self.group.count { Phase::RecordReserve } else { Phase::OperandGap };
        Ok(())
    }
    fn reserve_segment(&mut self) -> Result<(), ControlledError<Diagnostic>> {
        let offset = self.reader.base + self.group.start;
        let required = self.document.numbers.len().checked_add(self.group.count).ok_or(ControlledError::Overflow)?;
        if self.document.segments.len() >= self.max_commands || required > self.max_numbers {
            return Err(ControlledError::Original(failure(DiagnosticKind::Limit, offset)));
        }
        reserve(&mut self.document.segments, 1, self.max_commands, offset)?;
        reserve(&mut self.document.numbers, self.group.count, self.max_numbers, offset)?;
        self.group.first_number = self.document.numbers.len();
        self.group.end = self.reader.index;
        self.phase = if self.group.count == 0 { Phase::RecordSegment } else { Phase::RecordNumber };
        Ok(())
    }
    fn record_subpath(&mut self, closed: bool, offset: usize) -> Result<(), ControlledError<Diagnostic>> {
        let edge_count = self.document.edges.len().checked_sub(self.current_subpath_edge).ok_or(ControlledError::Overflow)?;
        if edge_count == 0 { return Ok(()); }
        reserve(&mut self.document.subpaths, 1, MAX_PATH_EDGES, offset)?;
        self.document.subpaths.push(PathSubpath { first_edge: self.current_subpath_edge, edge_count, closed });
        Ok(())
    }
    fn complete_segment(&mut self) -> Result<(), ControlledError<Diagnostic>> {
        self.document.segments[self.group.segment_index].edge_count = self.document.edges.len()
            .checked_sub(self.group.first_edge).ok_or(ControlledError::Overflow)?;
        Ok(())
    }
    fn check_points(&self, points: &[Point]) -> Result<(), ControlledError<Diagnostic>> {
        if points.iter().all(|point| flatten::bounded(*point)) { Ok(()) }
        else { Err(ControlledError::Original(failure(DiagnosticKind::Number, self.group_offset()))) }
    }
    fn group_offset(&self) -> usize { self.reader.base + self.group.group_start }
    fn next_gap(&mut self) { self.had_separator = false; self.phase = Phase::Gap; }
    fn start_geometry(&mut self, cursor: GeometryCursor, offset: usize, after: AfterGeometry) {
        self.geometry = Some(cursor); self.geometry_offset = offset; self.after_geometry = after; self.phase = Phase::Geometry;
    }
}

pub fn parse_path_controlled(source: &[u8], span: Span, transform: Affine, options: ParseOptions, control: &mut dyn WorkControl)
    -> Result<PathDocument, ControlledError<Diagnostic>> {
    let mut session = PathParseSession::new(source, span, transform, options)?;
    loop {
        match session.step(256, control) {
            ControlledStep::Pending { .. } => (),
            ControlledStep::Complete(()) => return session.finish(),
            ControlledStep::Failed(error) => return Err(error),
        }
    }
}

pub(crate) fn parse(source: &[u8], span: Span, transform: Affine, options: ParseOptions) -> Result<PathDocument, Diagnostic> {
    parse_path_controlled(source, span, transform, options, &mut NoStop).map_err(|error| legacy_error(error, span.start))
}
